// General parameters to unregister a request or notification.
#[derive(Clone, Debug, Default, PartialEq, Eq, Hash)]
pub struct Unregistration {
    // The id used to unregister the request or notification. Usually an id
    // provided during the register request.
    pub id: String,

    // The method to unregister for.
    pub method: String,
}

impl Json for Unregistration {
    const GO_TYPE: &'static str = "lsproto.Unregistration";
    const GO_POINTER: bool = true;

    fn to_json(&self) -> Value {
        let mut w = ObjectWriter::new(2);
        w.field("id", &self.id);
        w.field("method", &self.method);
        w.finish()
    }

    fn from_json(v: &Value) -> Result<Self, JsonError> {
        let mut s = Self::default();
        let Some(members) = struct_members(v, Self::GO_TYPE, true)? else {
            return Ok(s);
        };
        let mut seen = 0u64;
        for (k, v) in members {
            match k.as_str() {
                "id" => {
                    seen |= 1 << 0;
                    s.id = field(k, v)?;
                }
                "method" => {
                    seen |= 1 << 1;
                    s.method = field(k, v)?;
                }
                _ => {}
            }
        }
        check_required(seen, &["id", "method"], Self::GO_TYPE)?;
        Ok(s)
    }
}

